CSV_FIELDS=("repetition","warmup","elapsed_ns","termination","outcome","result_disposition","registry_verified","assurance","canonical_relation_checked","completeness_verifier","completeness_verifier_version","status","consumed_result_marker","objective_lower","objective_upper","distinct_histories_same_terminal_checked","four_box_corners_checked","error")
def canonical(value):return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":"),allow_nan=False).encode("utf-8")
def digest(value):return hashlib.sha256(canonical(value)).hexdigest()
def validate(record):
    errors=[]
    for key,expected in {"schema":SCHEMA,"source_commit":SOURCE_COMMIT,"report_id":REPORT_ID,"algorithm":ALGORITHM,"assumptions":EXPECTED_ASSUMPTIONS,"canonical_relation":RELATION,"evidence_limits":EXPECTED_EVIDENCE_LIMITS}.items():
        if record.get(key)!=expected:errors.append(key)
    scenario=record.get("scenario",{})
    if scenario.get("value")!=EXPECTED_SCENARIO:errors.append("scenario_contract")
    if scenario.get("sha256")!=digest(scenario.get("value")):errors.append("scenario_hash")
    m=record.get("measurement",{});events=m.get("events",[])
    if len(events)!=8 or [(e.get("repetition"),e.get("warmup")) for e in events]!=[(0,True),*[(i,False) for i in range(1,8)]]:errors.append("event_matrix")
    expected={"schema":EVENT_SCHEMA,"status":"passed","termination":"completed","outcome":"optimal","result_disposition":"complete_optimal_family","registry_verified":True,"assurance":"numerical","canonical_relation_checked":True,"completeness_verifier":"csl.verifier.ts02-constant-integrator","completeness_verifier_version":"1","lp_provider":ALGORITHM["lp_provider"],"convex_provider":ALGORITHM["convex_provider"],"objective_lower":3,"objective_upper":3,"distinct_histories_same_terminal_checked":True,"four_box_corners_checked":True,"error":""}
    providers=set(ALGORITHM["registered_providers"]+[ALGORITHM["strategy_id"]+"@1"])
    if any(any(e.get(k)!=v for k,v in expected.items()) or any(e.get(k) is not True for k in ("registry_verified","canonical_relation_checked","distinct_histories_same_terminal_checked","four_box_corners_checked")) or not providers.issubset(set(e.get("providers",[]))) or type(e.get("elapsed_ns")) is not int or e["elapsed_ns"]<0 or type(e.get("consumed_result_marker")) is not int or e["consumed_result_marker"]<=0 for e in events):errors.append("event_invalid")
    observed=[e.get("elapsed_ns") for e in events[1:]];summary=m.get("timing_ns",{})
    if len(observed)!=7 or any(type(v) is not int for v in observed) or summary.get("observations")!=observed:errors.append("timing_observations")
    elif any(summary.get(k)!=v for k,v in {"median":statistics.median(observed),"min":min(observed),"max":max(observed),"range":max(observed)-min(observed)}.items()):errors.append("timing_summary")
    if m.get("counts")!={"warmup":1,"measured":7,"passed":7,"failed":0,"all_outputs_consumed_and_validated":True}:errors.append("counts")
    for key,expected in {"scope":EXPECTED_SCOPE,"limiter":EXPECTED_LIMITER,"performance_conclusion":"inconclusive","result_observation":{"termination":"completed","outcome":"optimal","disposition":"complete_optimal_family","registry_verified":True,"assurance":"numerical","objective_lower":3,"objective_upper":3,"canonical_relation_checked_each_trial":True,"distinct_histories_same_terminal_checked_each_trial":True,"four_box_corners_checked_each_trial":True}}.items():
        if m.get(key)!=expected:errors.append(key)
    if m.get("phase_counters")!=EXPECTED_PHASE_COUNTERS:errors.append("phase_counters")
    source=m.get("source",{})
    if m.get("algorithm_source_commit")!=SOURCE_COMMIT or source.get("head")!=SOURCE_COMMIT or any(source.get(k) is not True for k in ("clean_before_build","clean_after_build","clean_after_run")):errors.append("source_provenance")
    if not isinstance(record.get("harness_commit"),str) or re.fullmatch(r"[0-9a-f]{40}",record["harness_commit"]) is None or m.get("harness_commit")!=record.get("harness_commit"):errors.append("harness_provenance")
    build=record.get("build",{})
    if m.get("build")!=build or any(build.get(k)!=v for k,v in {"configuration":"Release","compiler":"MSVC","cxx_standard":"C++20","ndebug":True,"generator":"Visual Studio 17 2022 x64"}.items()):errors.append("build_provenance")
    if m.get("environment")!=record.get("environment") or record.get("environment",{}).get("requested_resources")!={"total_threads":1,"outer_workers":1,"threads_per_worker":1,"memory_bytes":None}:errors.append("environment_provenance")
    profile=m.get("profile_attempt",{})
    if profile.get("separate_workload_return_code")!=0 or profile.get("separate_workload_timed_out") is not False:errors.append("profile_outcome")
    return errors

def render_html(record):
    errors=validate(record)
    if errors:raise ValueError("invalid SYN-03 T-S02 report: "+", ".join(errors))
    esc=lambda v:html.escape(str(v));m=record["measurement"];timing=m["timing_ns"]
    rows="".join(f'<tr><th scope="row">{e["repetition"]}</th><td>{e["elapsed_ns"]}</td><td>[3,3]</td><td>{esc(e["result_disposition"])}</td><td>{esc(e["status"])}</td></tr>' for e in m["events"][1:])
    dots="".join(f'<circle cx="{45+i*48}" cy="{190-v/max(timing["max"],1)*125:.2f}" r="4" fill="#087e8b"></circle>' for i,v in enumerate(timing["observations"]))
    limits="".join("<li>"+esc(x)+"</li>" for x in record["evidence_limits"])
    assumptions="".join("<li>"+esc(x)+"</li>" for x in record["assumptions"])
    return ''.join(['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SYN-03 Strategy A T-S02 report</title><style>body{font:16px system-ui,sans-serif;max-width:1000px;margin:2rem auto;padding:0 1rem;color:#18232d}table{border-collapse:collapse;display:block;overflow:auto}td,th{border:1px solid #bac6cc;padding:.45rem .7rem;text-align:left}pre{overflow:auto;background:#f4f7f8;padding:1rem}svg{max-width:100%;height:auto}.note{background:#fff4d6;padding:1rem}code{overflow-wrap:anywhere}</style></head><body>',
    '<h1>Registered Strategy A on the T-S02 constant-objective profile</h1><p>Single-profile exploratory evidence. One excluded warmup and seven saved observations; no comparator or speedup claim.</p>',
    '<p>Solver source <code>'+esc(record['source_commit'])+'</code>; separately versioned harness <code>'+esc(record['harness_commit'])+'</code>. Input SHA-256 <code>'+esc(record['scenario']['sha256'])+'</code>.</p><h2>Assumptions</h2><ul>'+assumptions+'</ul>',
    '<h2>Full optimal joint-history relation</h2><p>Every feasible history has objective 3. The complete relation is <code>(x0,x1,x2,u0,u1)=(0,s,s+t,s,t)</code> with <code>0≤s,t≤1</code>. Each timed run checked completed optimal status, registry-verified exact family, objective bounds [3,3], and every coefficient of the canonical H-relation.</p>',
    '<pre>0 ≤ u0,u1 ≤ 1; x0=0; x1−x0−u0=0; x2−x1−u1=0</pre><p>The distinct histories <code>(0,0,1,0,1)</code> and <code>(0,1,1,1,0)</code> both have terminal state 1. Each timed run checked both, the endpoint histories with terminal states 0 and 2, and two infeasible nonmembers. All membership arithmetic uses exactly representable binary64 integer literals.</p>',
    '<p>The registered completeness verifier is <code>csl.verifier.ts02-constant-integrator@1</code>, with <code>Assurance::numerical</code>. Strategy A performs forward reachability, terminal optimization and joint-history recovery before the T-S02 complete-family verifier accepts the full feasible relation. Analytical relation recovery is verified on this path. LP and geometry providers are registered production dependencies, and provider activity is part of the timed public path; native solver call counts and phase timings are unavailable.</p>',
    '<h2>Observed public-call timings</h2><p>'+esc(m['scope'])+'</p><p>Seven observations, median <strong>'+esc(timing['median'])+' ns</strong>; min–max '+esc(timing['min'])+'–'+esc(timing['max'])+' ns; range width '+esc(timing['range'])+' ns. Failures: 0. The excluded warmup is retained in JSONL/CSV.</p>',
    '<figure><svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Seven elapsed nanosecond observations" viewBox="0 0 390 220" width="390" height="220"><line x1="30" y1="190" x2="370" y2="190" stroke="#18232d"></line>'+dots+'<text x="200" y="215" text-anchor="middle">measured repetition</text><text x="10" y="30">'+esc(timing['max'])+' ns</text></svg><figcaption>Each dot is one saved observation; no outlier was removed.</figcaption></figure>',
    '<table><thead><tr><th>Repetition</th><th>Elapsed (ns)</th><th>Objective bounds</th><th>Result disposition</th><th>Validation</th></tr></thead><tbody>'+rows+'</tbody></table>',
    '<p class="note"><strong>Performance conclusion: inconclusive.</strong> '+esc(m['limiter']['reason'])+' The separate diagnostic run is retained in <a href="profile.json">profile evidence</a>; its durations are excluded from the seven observations.</p><h2>Evidence limits</h2><ul>'+limits+'</ul>',
    '<h2>Environment and reproduction</h2><p>Host/compiler/Release settings, exact source and harness identities, dependency hashes, executable hash, clean-source checks, pre/post host load, resources, warm-state policy, commands, and unavailable phase counters are retained below. Absolute host roots are replaced by portable placeholders. The build provenance retains original evidence hashes separately from the hashes of the sanitized published files. The interval includes registry preparation and verification; it is not a native-only solve interval.</p>',
    '<p><a href="records.json">Typed JSON</a> · <a href="measurement-events.jsonl">Raw JSONL</a> · <a href="trials.csv">Raw CSV</a> · <a href="measurement.json">Measurement</a> · <a href="scenarios.json">Scenario</a> · <a href="environment.json">Environment</a> · <a href="build-provenance.json">Build provenance</a> · <a href="commands.json">Commands</a> · <a href="profile.json">Separate profile</a> · <a href="README.md">Reproduction notes</a></p><p>This partial SYN-03 evidence keeps <a href="https://github.com/butahlecoq/controlled-systems-lab/issues/67">#66</a> open. Deployment and live URL verification are separate main-only gates.</p></body></html>'])

if __name__=="__main__":
    import argparse
    from pathlib import Path
    parser=argparse.ArgumentParser();parser.add_argument("--check",action="store_true");parser.add_argument("records");args=parser.parse_args()
    record=json.loads(Path(args.records).read_text(encoding="utf-8"));errors=validate(record)
    if errors:raise SystemExit(", ".join(errors))
    print("SYN-03 T-S02 report valid" if args.check else render_html(record))
